"""Run actual Chromium normal/reduced-motion checks for all animated SVG sources."""
import hashlib,json,subprocess,time
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime,timezone
from pathlib import Path
root=Path('/workspace/tiny-perceptron-vlm');sha=lambda b:hashlib.sha256(b).hexdigest();helper=Path('/tmp/check-svg-motion.mjs');program=helper.read_bytes();items=sorted(p for p in (root/'course/figures').glob('*.svg') if b'@keyframes' in p.read_bytes());assert len(items)==38;before={p.name:sha(p.read_bytes()) for p in items};out=root/'outputs/browser-layout/current-motion';out.mkdir(parents=True,exist_ok=True);start=time.perf_counter()
def check(p):
 shot=out/(p.stem+'.png');command=['node',str(helper),p.name,str(shot),'688'];r=subprocess.run(command,cwd=root,capture_output=True,text=True,timeout=60);r.check_returncode();data=json.loads(r.stdout);assert not data['text_outside_viewBox'],p.name;normal=data['defaultMotion'];reduced=data['reducedMotion'];assert not normal['reduced'] and normal['animations']>0 and reduced['reduced'] and reduced['animations']==0 and normal['text']==reduced['text'];assert all(t['display']!='none' and t['visibility']!='hidden' and float(t['opacity'])>0 for t in reduced['text']);assert before[p.name]==sha(p.read_bytes());return {'source':'course/figures/'+p.name,'source_sha256':before[p.name],'command':command,'exit_code':r.returncode,'stderr':r.stderr,'screenshot_sha256':sha(shot.read_bytes()),'actual_browser_result':data}
with ThreadPoolExecutor(max_workers=3) as pool:records=list(pool.map(check,items))
assert before=={p.name:sha(p.read_bytes()) for p in items}
receipt={'schema_version':1,'checked_at':datetime.now(timezone.utc).isoformat(),'status':'passed','scope':'Actual independent Chromium targets at 688 CSS pixels, normal motion then prefers-reduced-motion:reduce, for all 38 animated course SVG files. Each has normal animations, zero reduced animations, identical visible text styling, and text bounds inside viewBox. Screenshots were captured; this check does not claim human visual inspection, semantics, webpage layout, or remote Colab/GPU execution. Files without CSS keyframes are outside this motion check.','seconds':time.perf_counter()-start,'figure_count':len(records),'verification_program':Path(__file__).read_text(),'browser_program':program.decode(),'browser_program_sha256':sha(program),'records':records}
p=root/'outputs/browser-layout/current-review-svg-motion.json';p.write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'status':'passed','animated_figures':len(records),'output':str(p),'seconds':receipt['seconds']}))

