import fs from 'node:fs/promises';
import path from 'node:path';
const [name,output,widthArg='1120']=process.argv.slice(2);
if(!name||path.basename(name)!==name||!name.endsWith('.svg')||!output)throw new Error('Usage: node /tmp/render-course-svg.mjs FIGURE.svg OUTPUT.png [WIDTH]');
const source=await fs.readFile('/workspace/tiny-perceptron-vlm/course/figures/'+name,'utf8');
const box=source.match(/viewBox="([^"]+)"/)[1].trim().split(/\s+/).map(Number);
const width=Number(widthArg),height=Math.ceil(width*box[3]/box[2]);
const version=await (await fetch('http://127.0.0.1:9233/json/version')).json();
const socket=new WebSocket(version.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{socket.onopen=resolve;socket.onerror=reject;});
let id=0;const waiting=new Map();
socket.onmessage=e=>{const r=JSON.parse(e.data);if(r.id){const p=waiting.get(r.id);waiting.delete(r.id);r.error?p.reject(new Error(JSON.stringify(r.error))):p.resolve(r.result);}};
function call(method,params={},sessionId){const n=++id;return new Promise((resolve,reject)=>{waiting.set(n,{resolve,reject});socket.send(JSON.stringify({id:n,method,params,...(sessionId?{sessionId}:{})}));});}
const {targetId}=await call('Target.createTarget',{url:'about:blank'});
try{
 const {sessionId}=await call('Target.attachToTarget',{targetId,flatten:true});
 const page=(method,params={})=>call(method,params,sessionId);
 await page('Page.enable');
 await page('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:false});
 await page('Page.navigate',{url:'http://127.0.0.1:9411/figures/'+encodeURIComponent(name)+'?render='+Date.now()});
 await new Promise(r=>setTimeout(r,700));
 await page('Runtime.evaluate',{expression:'document.fonts.ready',awaitPromise:true});
 const motionState=async()=>{const r=await page('Runtime.evaluate',{expression:`(()=>{const svg=document.querySelector('svg');return {reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,animations:svg.getAnimations({subtree:true}).length,text:[...svg.querySelectorAll('text')].map(e=>({text:e.textContent,display:getComputedStyle(e).display,visibility:getComputedStyle(e).visibility,opacity:getComputedStyle(e).opacity}))}})()`,returnByValue:true});if(r.exceptionDetails)throw new Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
 const defaultMotion=await motionState();
 await page('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-motion',value:'reduce'}]});
 await new Promise(r=>setTimeout(r,150));
 const reducedMotion=await motionState();
 if(defaultMotion.reduced||defaultMotion.animations===0||!reducedMotion.reduced||reducedMotion.animations!==0||JSON.stringify(defaultMotion.text)!==JSON.stringify(reducedMotion.text)||reducedMotion.text.some(t=>t.display==='none'||t.visibility==='hidden'||Number(t.opacity)===0))throw new Error('Reduced-motion check failed');

 const bounds=await page('Runtime.evaluate',{expression:`(()=>{const s=document.querySelector('svg');if(!s)throw new Error('Expected SVG, got '+document.title);const b=s.viewBox.baseVal;return [...s.querySelectorAll('text')].map(e=>{const r=e.getBBox(),m=s.getCTM().inverse().multiply(e.getCTM());const p=[[r.x,r.y],[r.x+r.width,r.y],[r.x,r.y+r.height],[r.x+r.width,r.y+r.height]].map(([x,y])=>new DOMPoint(x,y).matrixTransform(m));return {text:e.textContent,x:Math.min(...p.map(p=>p.x)),y:Math.min(...p.map(p=>p.y)),right:Math.max(...p.map(p=>p.x)),bottom:Math.max(...p.map(p=>p.y))}}).filter(t=>t.x<b.x-0.001||t.y<b.y-0.001||t.right>b.x+b.width+0.001||t.bottom>b.y+b.height+0.001)})()`,returnByValue:true});
 if(bounds.exceptionDetails)throw new Error(JSON.stringify(bounds.exceptionDetails));
 console.log(JSON.stringify({figure:name,viewport:{width,height},text_outside_viewBox:bounds.result.value,defaultMotion,reducedMotion}));
 const shot=await page('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
 await fs.writeFile(output,Buffer.from(shot.data,'base64'));
}finally{await call('Target.closeTarget',{targetId});socket.close();}
